module parity_8bit (
    input [7:0] in,
    output out
);

wire top_xor = in[1] ^ in[0];
wire top_xnor = ~(in[3] ^ in[2]);
wire mid_xor1 = top_xor ^ top_xnor;

wire bot_xor = in[5] ^ in[4];
wire bot_xnor = ~(in[7] ^ in[6]);
wire mid_xor2 = bot_xor ^ bot_xnor;

assign out = mid_xor1 | mid_xor2;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire mux_out;
    wire and1_out, and2_out, and3_out, and4_out, and5_out;
    wire or1_out, or2_out;
    wire not1_out;

    // Bottom 2-to-1 MUX controlled by sel[0]
    assign mux_out = (sel[0] == 1'b0) ? in[2] : in[3];

    // Lower AND gates (active low outputs - bubbles)
    assign and1_out = ~(in[1] & sel[1]);
    assign and2_out = ~(in[0] & sel[1]);
    assign and3_out = ~(in[2] & sel[0]);

    // Inverter
    assign not1_out = ~sel[1];

    // Upper AND gates (active low outputs - bubbles)
    assign and4_out = ~(not1_out & sel[0]);
    assign and5_out = ~(and4_out & and1_out);

    // OR gates
    assign or1_out = and5_out | mux_out;
    assign or2_out = or1_out | and2_out;

    // Final output
    assign out = or2_out;

endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (c & b) | (c & a) | (b & a);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    wire xor1_out = binary[1] ^ binary[3];
    wire xor2_out = binary[2] ^ binary[3];
    wire xor3_out = binary[0] ^ binary[2];

    // The diagram shows gray receives a single input from the mux output (likely channel 1).
    // Other bits of gray are not shown connected, so they are set to 0.
    assign gray[0] = xor1_out; // Assuming mux selects channel 1.
    assign gray[3:1] = 3'b000;
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire xnor0_out, xnor1_out, xnor2_out, xnor3_out;
    wire nand1_out, and1_out;

    assign xnor0_out = ~(b[0] ^ a[0]);
    assign xnor1_out = ~(b[1] ^ a[1]);
    assign xnor2_out = ~(a[2] ^ b[2]);
    assign xnor3_out = ~(a[3] ^ b[3]);

    assign nand1_out = ~(xnor0_out & xnor1_out);
    assign and1_out = xnor2_out & xnor3_out;

    assign equal = ~(nand1_out & and1_out);

endmodule

module decoder_2to4 (
