module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg q0, q1, q2;
    wire d0, d1, d2;
    wire n0, n1, n2, n3, n4, n5, n6, n7, n8;

    assign n0 = ~(reset | q0);
    assign n1 = ~(q0 & reset);
    assign n2 = ~(q1 | q2);
    assign n3 = ~(q0 & n1);
    assign n4 = ~(q1 & n2);
    assign n5 = ~(n3 & n4);
    assign d0 = n0;
    assign d1 = n1;
    assign d2 = n2;

    always @(posedge clk) begin
        q0 <= d0;
        q1 <= d1;
        q2 <= d2;
    end

    assign n6 = ~(q0 & q1);
    assign n7 = ~(q1 | q2);
    assign n8 = ~(q0 & n2);
    assign light[0] = n6;
    assign light[1] = n7;
    assign light[2] = n8;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] state, next_state;

always @(*) begin
    next_state[0] = (state[1] | clk) & ~(state[0] & reset) & ~coin_inserted;
    next_state[1] = (state[0] | reset) & ~(state[1] & clk) & ~(coin_inserted & item_selected);
end

always @(posedge item_selected) begin
    state <= next_state;
end

assign state = state;

endmodule

