module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire nand012 = ~(data_in[1] & data_in[2]);
    wire nand345 = ~(data_in[3] & data_in[4]);
    wire nand567 = ~(data_in[5] & data_in[6]);
    wire nand700 = ~(data_in[7] & data_in[0]);

    assign data_out[0] = ~data_in[0] | nand012;
    assign data_out[1] = ~data_in[0] ^ data_in[1];
    assign data_out[2] = nand012 | data_in[3];
    assign data_out[3] = data_in[2] ^ nand345;
    assign data_out[4] = nand345 | data_in[5];
    assign data_out[5] = data_in[4] ^ nand567;
    assign data_out[6] = nand567 | data_in[7];
    assign data_out[7] = data_in[6] ^ nand700;
endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    wire [7:0] v = data_in;
    wire [7:0] result;

    // Bit 0: XOR of (NOT v[1]) and (v[2] AND v[3])
    assign result[0] = (~v[1]) ^ (v[2] & v[3]);

    // Bit 1: XOR of v[2] and (v[2] AND v[3])
    assign result[1] = v[2] ^ (v[2] & v[3]);

    // Bit 2: XOR of v[3] and (v[4] OR v[5])
    assign result[2] = v[3] ^ (v[4] | v[5]);

    // Bit 3: XOR of (v[4] OR v[5]) and v[6]
    assign result[3] = (v[4] | v[5]) ^ v[6];

    // Bit 4: XOR of v[5] and NOT(v[6] OR v[7])
    assign result[4] = v[5] ^ ~(v[6] | v[7]);

    // Bit 5: XOR of ((v[0] AND v[1]) OR (v[2] AND v[3])) and NOT(v[6] OR v[7])
    assign result[5] = ((v[0] & v[1]) | (v[2] & v[3])) ^ ~(v[6] | v[7]);

    // Bit 6: XOR of NOT(v[0] OR v[1]) and NOT(v[2] AND v[3])
    assign result[6] = ~(v[0] | v[1]) ^ ~(v[2] & v[3]);

    // Bit 7: XOR of NOT(v[0] AND v[1]) and NOT(v[2] OR v[3])
    assign result[7] = ~(v[0] & v[1]) ^ ~(v[2] | v[3]);

    assign data_out = result;

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [7:0] demux_out;
    wire [3:0] sel;

    assign sel = data_in[3:0];

    // 1-to-8 Demultiplexer
    assign demux_out[0] = (sel == 4'd0);
    assign demux_out[1] = (sel == 4'd1);
    assign demux_out[2] = (sel == 4'd2);
    assign demux_out[3] = (sel == 4'd3);
    assign demux_out[4] = (sel == 4'd4);
    assign demux_out[5] = (sel == 4'd5);
    assign demux_out[6] = (sel == 4'd6);
    assign demux_out[7] = (sel == 4'd7);

    // XOR gates
    wire xor_out_4 = demux_out[0] ^ demux_out[4];
    wire xor_out_5 = demux_out[1] ^ demux_out[5];
    wire xor_out_6 = demux_out[2] ^ demux_out[6];
    wire xor_out_7 = demux_out[3] ^ demux_out[7];

    // MUX inputs
    wire [7:0] mux_in;
    assign mux_in[0] = demux_out[0];
    assign mux_in[1] = demux_out[1];
    assign mux_in[2] = demux_out[2];
    assign mux_in[3] = demux_out[3];
    assign mux_in[4] = xor_out_4;
    assign mux_in[5] = xor_out_5;
    assign mux_in[6] = xor_out_6;
    assign mux_in[7] = xor_out_7;

    // 8-to-1 Multiplexer
    assign data_out[3:0] = mux_in[sel];
    assign data_out[7:4] = 4'b0000;

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

    reg q;
    wire d;
    assign d = q;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q <= 1'b0;
        else
            q <= d;
    end

    assign clk_out = ~q;

endmodule

