module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);
    assign out[0] = ~(enable & ~in[0]);
    assign out[1] = ~(enable & ~(in[1] | ~in[0]));
    assign out[2] = ~(in[1] & ~enable);
    assign out[3] = ~(~(in[0] & in[1]) & enable);
endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
    wire not_val0_1;
    wire and0, and1, and2, and3, and4;
    wire or1;
    wire [1:0] select;
    reg [7:0] out_reg;

    assign select = in[1:0];

    not(not_val0_1, in[1]);
    and(and0, in[0], not_val0_1);
    and(and1, in[0], in[1]);
    and(and2, enable, in[1]);
    or(or1, and1, and2);
    and(and3, enable, not_val0_1);
    and(and4, or1, and3);

    always @(*) begin
        case(select)
            2'b00: out_reg = {8{and0}};
            2'b01: out_reg = {8{or1}};
            2'b10: out_reg = {8{and3}};
            2'b11: out_reg = {8{and4}};
            default: out_reg = 8'b0;
        endcase
    end

    assign out = out_reg;
endmodule

