module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg q0, q1, q2, q3, q4, q5, q6, q7;
    wire d0, d1, d2, d3, d4, d5, d6, d7;
    wire n0, n1, n2, n3, n4, n5, n6, n7;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q0 <= 1'b0;
            q1 <= 1'b0;
            q2 <= 1'b0;
            q3 <= 1'b0;
            q4 <= 1'b0;
            q5 <= 1'b0;
            q6 <= 1'b0;
            q7 <= 1'b0;
        end else begin
            q0 <= d0;
            q1 <= d1;
            q2 <= d2;
            q3 <= d3;
            q4 <= d4;
            q5 <= d5;
            q6 <= d6;
            q7 <= d7;
        end
    end

    assign n0 = ~q0;
    assign n1 = ~q1;
    assign n2 = ~q2;
    assign n3 = ~q3;
    assign n4 = ~q4;
    assign n5 = ~q5;
    assign n6 = ~q6;
    assign n7 = ~q7;

    assign d0 = clk ^ q1 ^ q2;
    assign d1 = q0 ^ rst ^ q3;
    assign d2 = q1 ^ q4 ^ n5;
    assign d3 = q2 ^ q5 ^ n6;
    assign d4 = q3 ^ q6 ^ q7;
    assign d5 = n0 ^ q4 ^ q7;
    assign d6 = q0 ^ n1 ^ q5;
    assign d7 = q2 ^ q6 ^ n7;

    assign count[0] = q0 ^ q4;
    assign count[1] = 1'b0;
    assign count[2] = q1 ^ q5;
    assign count[3] = 1'b0;
    assign count[4] = 1'b0;
    assign count[5] = q2 ^ q6;
    assign count[6] = q3 ^ q7;
    assign count[7] = q0 ^ q1;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
    reg q0, q1, q2, q3;
    always @(*) begin
        if (rst) begin
            q0 = 1'b0;
            q1 = 1'b0;
            q2 = 1'b0;
            q3 = 1'b0;
        end else begin
            q0 = clk;
            q1 = clk;
            q2 = ~clk;
            q3 = ~clk;
        end
    end
    assign q = {q0, q1, q2, q3};
endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

reg [7:0] shift_reg;
wire nand_out;

assign nand_out = ~(rst & load & pin[0]);

always @(posedge clk or posedge load) begin
    if (load) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg[0] <= nand_out;
        shift_reg[1] <= rst ? pin[1] : shift_reg[0];
