module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg q1, q2, q3, q4;
  wire nand_out, nor1_out, nor2_out;
  wire d4;

  // First D flip-flop
  always @(posedge clk or posedge reset) begin
    if (reset)
      q1 <= 1'b0;
    else
      q1 <= reset;
  end

  // Second D flip-flop
  always @(posedge clk or posedge reset) begin
    if (reset)
      q2 <= 1'b0;
    else
      q2 <= q1;
  end

  // Third D flip-flop
  always @(posedge clk or posedge reset) begin
    if (reset)
      q3 <= 1'b0;
    else
      q3 <= q2;
  end

  // NAND gate
  assign nand_out = ~(q2 & q3);

  // First NOR gate
  assign nor1_out = ~(q3 | data);

  // Second NOR gate
  assign nor2_out = ~(nand_out | nor1_out);

  // D input for fourth flip-flop
  assign d4 = nor2_out;

  // Fourth D flip-flop with enable (always enabled)
  always @(posedge clk or posedge data) begin
    if (data)
      q4 <= 1'b0;
    else if (1'b1)
      q4 <= d4;
  end

  assign start_shifting = q4;

endmodule

