module adder_32bit(A,B,S,C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire [16:1] sum_low;
    wire [16:1] sum_high;
    wire cout_low;

    // Lower 16-bit CLA (bits 1-16)
    cla_16bit cla_low (
        .a(A[16:1]),
        .b(B[16:1]),
        .cin(1'b0),
        .sum(sum_low),
        .cout(cout_low)
    );

    // Upper 16-bit CLA (bits 17-32)
    cla_16bit cla_high (
        .a(A[32:17]),
        .b(B[32:17]),
        .cin(cout_low),
        .sum(sum_high),
        .cout(C32)
    );

    // Concatenate the sums
    assign S = {sum_high, sum_low};

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [8:0] carry;
    assign carry[0] = cin;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin : adder_bit
            assign sum[i] = a[i] ^ b[i] ^ carry[i];
            assign carry[i+1] = (a[i] & b[i]) | (a[i] & carry[i]) | (b[i] & carry[i]);
        end
    endgenerate

    assign cout = carry[8];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

wire [4:0] binary_sum;
wire correction_needed;
wire [3:0] corrected_sum;

// First stage: 4-bit binary addition with carry-in
assign binary_sum = A + B + Cin;

// Check if correction is needed (sum > 9 or carry-out from binary addition)
assign correction_needed = binary_sum[4] | (binary_sum[3] & binary_sum[2]) | (binary_sum[3] & binary_sum[1]);

// Apply BCD correction by adding 6 if needed
assign corrected_sum = binary_sum[3:0] + (correction_needed ? 4'd6 : 4'd0);

// Final outputs
assign Sum = corrected_sum;
assign Cout = correction_needed;

endmodule

module comparator_3bit (
