);
    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12, w13, w14, w15, w16, w17;

    assign w1 = ~(B[1] & B[2]);
    assign w2 = ~(B[1] ^ B[2]);
    assign w3 = ~A[2];
    assign w4 = ~(A[0] & A[1]);
    assign w5 = ~(A[0] ^ A[1]);
    assign w6 = w4 & w5;
    assign w7 = w3 & w6;
    assign w8 = w7 & w2;
    assign w9 = w8 & w1;
    assign w10 = ~(B[0] ^ A[0]);
    assign w11 = w10 ^ A[1];
    assign w12 = w11 | w7;
    assign w13 = w12 & w9;
    assign w14 = ~(w13 & B[2]);
    assign w15 = ~(B[2] & A[2]);
    assign w16 = w15 | w13;
    assign w17 = w16 & A[1];

    assign A_less = w13;
    assign A_greater = ~w14;
    assign A_equal = w17;
endmodule

