module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  reg q0, q1, q2, q3;
  wire d0, d1, d2, d3;
  wire e0, e1, e2, e3;
  wire r0, r1, r2, r3;

  assign e0 = rst_n;
  assign e1 = rst_n;
  assign e2 = rst_n;
  assign e3 = rst_n;

  assign r0 = valid_count;
  assign r1 = valid_count;
  assign r2 = valid_count;
  assign r3 = valid_count;

  assign d0 = rst_n ^ q2;
  assign d1 = rst_n ^ q3;
  assign d2 = rst_n & q0;
  assign d3 = rst_n & q1;

  always @(posedge clk or posedge valid_count) begin
    if (valid_count) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
    end else begin
      if (e0) q0 <= d0;
      if (e1) q1 <= d1;
      if (e2) q2 <= d2;
      if (e3) q3 <= d3;
    end
  end

  always @(*) begin
    out[0] = ~(q0 & q2) ^ (q1 | q3);
    out[1] = ~(q0 & q2) & ~(q1 | q3);
    out[2] = q0 ^ q1 ^ rst_n;
    out[3] = ~(q2 ^ q3) & rst_n;
  end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg q1;
wire nand_top_out;
wire nand_bot_out;

// DFF1
always @(posedge nand_bot_out or posedge rst_n) begin
	if (rst_n)
		q1 <= 1'b0;
	else
		q1 <= a;
end

// DFF2
always @(posedge clk or posedge a) begin
	if (a)
		rise <= 1'b0;
	else
		rise <= nand_top_out;
end

// DFF3
always @(posedge rst_n or posedge a) begin
	if (a)
		down <= 1'b0;
	else
		down <= nand_bot_out;
end

// NAND gates
assign nand_top_out = ~(clk & q1);
assign nand_bot_out = ~(rst_n & q1);

endmodule

