module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  reg ff0, ff1, ff2;
  wire xor_out;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      ff0 <= 1'b0;
      ff1 <= 1'b0;
      ff2 <= 1'b0;
    end else begin
      ff0 <= rst;
      ff1 <= ff0;
      ff2 <= xor_out;
    end
  end

  assign xor_out = ff0 ^ ff1;

  always @(*) begin
    out[0] = ff0;
    out[1] = xor_out;
    out[2] = ff1;
    out[3] = ff2;
  end
endmodule

module right_shifter(clk, q, d);
    input clk;
    input d;
    output [7:0] q;

    reg [7:0] shift_reg;

    always @(posedge clk) begin
        shift_reg <= {shift_reg[6:0], d};
    end

    assign q = shift_reg;
endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	reg [3:0] data_reg;

	always @(posedge clk_a or posedge clk_b) begin
		if (clk_b) begin
			data_reg <= 4'b0000;
		end else if (data_en) begin
			case (data_in[1:0])
				2'b00: data_reg <= {data_reg[2:0], arstn};
				2'b01: data_reg <= {data_reg[2:0], brstn};
				2'b10: data_reg <= {data_reg[2:0], data_in[0]};
				2'b11: data_reg <= {data_reg[2:0], data_in[1]};
			endcase
		end
	end

	always @(posedge clk_a or posedge clk_b) begin
		if (clk_b) begin
			dataout <= 4'b0000;
		end else begin
			dataout <= data_reg;
		end
	end

endmodule

module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);
    always @(*) begin
        case (addr[1:0])
            2'b01: dout = 16'h0000;
            2'b11: dout = 16'h0001;
            2'b00: dout = 16'h0000;
            default: begin
                case (addr[0])
                    1'b1: dout = 16'h0000;
                    1'b0: begin
                        case (addr[1])
                            1'b0: dout = 16'h0001;
                            default: dout = 16'h0000;
                        endcase
                    end
                endcase
            end
        endcase
    end
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

    reg Q0, Q1, Q2, Q3;

    always @(posedge rst_n or posedge data_in) begin
        if (data_in) begin
            Q0 <= 1'b0;
            Q1 <= 1'b0;
            Q2 <= 1'b0;
            Q3 <= 1'b0;
        end else begin
            // Logic for D0 (S_DFF_PN0)
            Q0 <= clk & Q1;
            // Logic for D1 (S_DFF_PN0)
            Q1 <= ~(clk & Q0);
            // Logic for D2 (S_DFF_PN0)
            Q2 <= Q0 & Q1;
            // Logic for D3 (S_DFF_PN1)
            Q3 <= (~ (Q2 | Q3)) | (Q1 | Q2);
        end
    end

    assign sequence_detected = Q3;

endmodule
